package com.donutsmp.gamehub.config;
import com.google.gson.*;import net.fabricmc.loader.api.FabricLoader;import java.io.IOException;import java.nio.file.Files;import java.nio.file.Path;
public record ClientSettings(String backendUrl){private static final Gson GSON=new GsonBuilder().setPrettyPrinting().create();public static ClientSettings load(){Path file=FabricLoader.getInstance().getConfigDir().resolve("donutsmp-gamehub.json");try{if(!Files.exists(file)){String u="https://donutsmp-game-hub-api.onrender.com";JsonObject o=new JsonObject();o.addProperty("backendUrl",u);Files.writeString(file,GSON.toJson(o));return new ClientSettings(u);}JsonObject o=GSON.fromJson(Files.readString(file),JsonObject.class);String u=o!=null&&o.has("backendUrl")&&o.get("backendUrl").isJsonPrimitive()?o.get("backendUrl").getAsString().trim():"";return new ClientSettings(u);}catch(IOException|RuntimeException e){return new ClientSettings("");}}}